   139  static bool LoadPSD(QDataStream &stream, const PSDHeader &header, QImage &img)
   140  {
   141      // Mode data
   142      skip_section(stream);
   143
   144      // Image resources
   145      skip_section(stream);
   146
   147      // Reserved data
   148      skip_section(stream);
   149
   150      // Find out if the data is compressed.
   151      // Known values:
   152      //   0: no compression
   153      //   1: RLE compressed
   154      quint16 compression;
   155      stream >> compression;
   156
   157      if (compression > 1) {
   158          qDebug() << "Unknown compression type";
   159          return false;
   160      }
   161
   162      quint32 channel_num = header.channel_count;
   163
   164      QImage::Format fmt = QImage::Format_RGB32;
   165      // Clear the image.
   166      if (channel_num >= 4) {
   167          // Enable alpha.
   168          fmt = QImage::Format_ARGB32;
   169
   170          // Ignore the other channels.
   171          channel_num = 4;
   172      }
   173      img = QImage(header.width, header.height, fmt);
   174      img.fill(qRgb(0,0,0));
   175
   176      const quint32 pixel_count = header.height * header.width;
   177
   178      QRgb *image_data = reinterpret_cast<QRgb*>(img.bits());
   179
   180      if (!image_data) {
   181          return false;
   182      }
   183
   184      static const channelUpdater updaters[4] = {
   185          updateRed,
   186          updateGreen,
   187          updateBlue,
   188          updateAlpha
   189      };
   190
   191      if (compression) {
   192          // Skip row lengths.
   193          int skip_count = header.height * header.channel_count * sizeof(quint16);
   194          if (stream.skipRawData(skip_count) != skip_count) {
   195              return false;
   196          }
   197
   198          for (unsigned short channel = 0; channel < channel_num; channel++) {
   199              bool success = decodeRLEData(RLEVariant::PackBits, stream,
   200                                           image_data, pixel_count,
   201                                           &readPixel, updaters[channel]);
   202              if (!success) {
   203                  qDebug() << "decodeRLEData on channel" << channel << "failed";
   204                  return false;
   205              }
   206          }
   207      } else {
   208          for (unsigned short channel = 0; channel < channel_num; channel++) {
   209              for (unsigned i = 0; i < pixel_count; ++i) {
   210                  image_data[i] = updaters[channel](image_data[i], readPixel(stream));
   211              }
   212              // make sure we didn't try to read past the end of the stream
   213              if (stream.status() != QDataStream::Ok) {
   214                  qDebug() << "DataStream status was" << stream.status();
   215                  return false;
   216              }
   217          }
   218      }
   219
   220      return true;
   221  }
